def seed_myanmar_translations(apps, schema_editor):
    TextKeyModel = apps.get_model("core", "TextKeyModel")
    TranslationModel = apps.get_model("core", "TranslationModel")
    LanguageModel = apps.get_model("core", "LanguageModel")

    languages = {lang.code: lang for lang in LanguageModel.objects.all()}
    mm = languages.get("mm")
    en = languages.get("en")

    for key, english, myanmar in MYANMAR_TEXTS:
        text_key, _ = TextKeyModel.objects.get_or_create(
            key=key, defaults={"default_text": english}
        )
        if mm:
            TranslationModel.objects.get_or_create(
                language=mm, text_key=text_key, defaults={"translated_text": myanmar}
            )
        if en:
            TranslationModel.objects.get_or_create(
                language=en, text_key=text_key, defaults={"translated_text": english}
            )


def remove_myanmar_translations(apps, schema_editor):
    TextKeyModel = apps.get_model("core", "TextKeyModel")
    TextKeyModel.objects.filter(key__in=[key for key, _, _ in MYANMAR_TEXTS]).delete()


